def build_recommendation(decision:dict,results:list[dict])->dict:
    if not results: return {"winner":"No recommendation yet","score":0,"summary":"Add at least two options.","advantage":"—","tradeoff":"—","uncertainty":"—","switch_condition":"—","next_step":"Add options.","close":False,"violations":[]}
    top=results[0]; close=len(results)>1 and abs(top["overall"]-results[1]["overall"])<5
    return {"winner":top["name"],"score":top["overall"],"summary":"Highest score under current priorities and assumptions." if not close else "The leading options are close; small assumption changes may change the ranking.","advantage":top.get("benefit") or "Its current lens balance is strongest.","tradeoff":top.get("concern") or "A major concern has not been specified.","uncertainty":"; ".join(top["uncertainties"]) or "Real outcomes may differ from these estimates.","switch_condition":top.get("switch_condition") or f"Reconsider {top['name']} if its key assumptions fail or another option better meets your constraints.","next_step":decision.get("recommended_next_step") or f"Run a small, time-boxed test of {top['name']} and define one observable success measure.","close":close,"violations":top["violations"]}
